// OTHVM — Gmail Check: one batched Gemini classification request for all emails.
const msgs = $input.all().map((i) => i.json).filter((j) => j && !j.error && j.id);
if (!msgs.length) return [];
const pick = (m, keys) => {
  for (const k of keys) {
    if (m[k] !== undefined && m[k] !== null && String(m[k]).trim() !== '') return String(m[k]);
  }
  return '';
};
const headers = (m) => (m.headers && typeof m.headers === 'object' ? m.headers : {});
const compact = msgs.map((m) => {
  const h = headers(m);
  const labels = Array.isArray(m.labelIds) ? m.labelIds : [];
  const unread = labels.includes('UNREAD');
  const starred = labels.includes('STARRED');
  const importantLabel = labels.includes('IMPORTANT');
  const score = (unread ? 3 : 0) + (starred ? 2 : 0) + (importantLabel ? 1 : 0);
  return {
    id: m.id,
    from: pick(m, ['from', 'From']) || pick(h, ['from', 'From']),
    subject: pick(m, ['subject', 'Subject']) || pick(h, ['subject', 'Subject']),
    date: pick(m, ['date', 'Date']) || pick(h, ['date', 'Date']),
    snippet: String(pick(m, ['snippet', 'textPlain', 'textAsHtml']) || '').slice(0, 180),
    unread,
    score,
  };
}).sort((a, b) => b.score - a.score).slice(0, 12);
if (!compact.length) return [];
const lines = compact.map((e, i) =>
  (i + 1) + '. ID: ' + e.id + '\nFrom: ' + e.from + '\nSubject: ' + e.subject + '\nSnippet: ' + e.snippet
);
const prompt = 'Classify each email as IMPORTANT or NOT_IMPORTANT.\n' +
  'IMPORTANT = requires human reply or urgent action.\n' +
  'Return ONLY a JSON array of objects with keys "id" (string) and "important" (boolean), one object per email, no markdown.\n\n' +
  'Emails:\n' + lines.join('\n\n');
return [{ json: { emails: compact, prompt } }];

// OTHVM — Gmail Check: parse the single batched Gemini classification.
const emails = $('Prepare Triage').first().json.emails || [];
let text = '';
try {
  text = (((($input.first().json || {}).candidates || [])[0] || {}).content || {}).parts.map((p) => p.text || '').join('').trim();
} catch (e) { text = ''; }
let parsed = null;
try { parsed = JSON.parse(text); } catch (e) {}
if (!Array.isArray(parsed) && parsed && Array.isArray(parsed.results)) parsed = parsed.results;
if (!Array.isArray(parsed)) {
  parsed = [];
  const re = /"id"\s*:\s*"([^"]+)"\s*,\s*"important"\s*:\s*(true|false)/gi;
  let m;
  while ((m = re.exec(text)) !== null) parsed.push({ id: m[1], important: m[2].toLowerCase() === 'true' });
}
const importantIds = new Set(parsed
  .filter((x) => x && (x.important === true || String(x.important).toLowerCase() === 'true'))
  .map((x) => String(x.id)));
const important = emails.filter((e) => importantIds.has(String(e.id)));
if (!important.length) return [];
const lines = important.map((e) => '• من: ' + (e.from || 'غير معروف') + ' — الموضوع: ' + (e.subject || '(بدون موضوع)') + (e.unread ? ' (غير مقروء)' : ''));
return [{ json: { message: '📬 إيميلات مهمة (' + important.length + '):\n' + lines.join('\n') } }];
